/* Alle stijlen horen uitsluitend bij de zelfstandige docentweergave. */
.detail .student-facts {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px 32px;margin:24px 0 30px;padding:22px 0;border-block:1px solid #d5e6f0;}
.detail .student-facts div {min-width:0;}
.detail .student-facts dt {margin:0 0 6px;font-size:12px;font-weight:500;color:#718aa4;letter-spacing:0;}
.detail .student-facts dd {margin:0;font-size:14px;font-weight:600;line-height:1.6;color:#183c63;overflow-wrap:anywhere;}
.detail .dossier-section-title {font-size:16px;font-weight:600;letter-spacing:0;margin:0 0 16px;}
.detail .dossier-outcome {display:grid;grid-template-columns:minmax(0,1fr) 100px 160px;align-items:start;gap:20px;padding:20px 0;border-top:1px solid #d5e6f0;}
.detail .dossier-outcome-main {min-width:0;}
.detail .dossier-outcome-main small {font-size:11px;overflow-wrap:anywhere;}
.detail .dossier-outcome h4 {margin:5px 0 0;font-size:15px;font-weight:600;line-height:1.5;letter-spacing:0;overflow-wrap:anywhere;}
.detail .dossier-outcome p {margin:10px 0 0;font-size:13px;color:#54748e;line-height:1.7;}
.detail .dossier-status {justify-self:start;background:#edf2f7;color:#52677e;white-space:normal;}
.detail .dossier-status-done {background:#e3f6ed;color:#087e65;}
.detail .dossier-status-active {background:#e6f1ff;color:#1664ac;}
.detail .dossier-updated {display:grid;gap:6px;font-size:12px;line-height:1.5;font-variant-numeric:tabular-nums;}
.detail .dossier-updated span {color:#718aa4;}
@media(max-width:620px) {
    .detail .student-facts {grid-template-columns:1fr;gap:18px;}
    .detail .dossier-outcome {grid-template-columns:minmax(0,1fr) auto;gap:12px;}
    .detail .dossier-updated {grid-column:1/-1;display:flex;flex-wrap:wrap;gap:8px;}
}
