er;font-size:11px}.report-row{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:13px 0;font-size:11px}.report-row i{display:inline-block;background:#155c9e;width:7px;height:7px;border-radius:50%;margin-right:8px}.report-row i.light{background:#d5e6f0}.footnote{font-size:10px;line-height:1.7;color:#718aa4;margin:18px 0 0}.bottom-columns{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.empty{text-align:center;padding:30px 10px;color:#54748e}.empty strong{display:block;font-size:14px}.empty p{font-size:12px;color:#718aa4;margin:10px auto;max-width:320px}.empty-symbol{display:grid;place-content:center;width:48px;height:48px;border-radius:14px;background:#e7f2fb;margin:0 auto 16px;font-size:25px}.meeting{display:flex;gap:17px;padding:16px 0;border-bottom:1px solid var(--line)}.meeting p{font-size:12px;margin:0 0 5px;color:#718aa4}.calendar{border:1px solid #d5e6f0;background:#f7fafc;border-radius:9px;align-self:start;min-width:56px;text-align:center;padding:10px 5px}.calendar strong{font-size:22px}.calendar small{font-size:9px}.history{border-top:1px solid var(--line);padding-top:16px;margin-top:16px;font-size:11px;color:#54748e}.history-item{padding:15px 0;border-bottom:1px solid var(--line)}.history-item p{font-size:12px}.note{background:#f7fafc;border:1px solid #e7eef4;border-radius:9px;padding:15px;margin-bottom:12px}.note>div{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px}.note p{font-size:12px;color:#54748e;margin:10px 0}.note-type{font-size:9px;color:#6487aa}.preserve{white-space:pre-wrap;overflow-wrap:anywhere}.detail{margin-top:22px;scroll-margin-top:20px}.detail .section-heading p{font-size:12px;color:#718aa4;margin:9px 0 0}.detail a{font-size:12px}.outcomes{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.outcomes article{border:1px solid var(--line);padding:18px;border-radius:9px}.outcomes h3{margin:8px 0 12px}.outcomes article>small:last-child{margin-top