/* De indeling blijft leesbaar op tablets en telefoons. */
@media(min-width:1700px){main{padding-top:42px}.hero{min-height:285px;padding:36px 44px}}
@media(max-width:1200px){.sidebar{width:210px;padding:28px 18px}.workspace{margin-left:210px}main{padding:28px 24px}.topbar{padding:0 24px}.columns{grid-template-columns:1fr}.columns>#rapportages{display:block}.metrics{gap:10px}.metric{padding:15px}.brand{font-size:14px}.brand-icon{width:30px;margin-right:5px}}
@media(max-width:760px){.sidebar{position:static;width:100%;padding:18px 20px}.brand{font-size:17px}.nav-caption,.sidebar-bottom{display:none}.sidebar nav{display:flex;overflow-x:auto;gap:7px;margin-top:18px}.sidebar nav a{padding:10px;font-size:13px;white-space:nowrap}.sidebar nav a span{font-size:10px}.sidebar nav b{display:none}.sidebar form{position:absolute;right:20px;top:17px}.logout{margin:0;padding:10px;border:0;font-size:10px}.workspace{margin:0}.topbar{height:48px;font-size:10px;padding:0 20px}main{padding:25px 16px}.page-heading{align-items:start}.page-heading .button{font-size:10px;padding:10px}.page-heading h1{font-size:28px}.page-heading p:not(.eyebrow){font-size:11px}.hero{padding:25px;min-height:245px}.hero-art{display:none}.hero h2{font-size:29px}.hero-tag{font-size:8px}.metrics{grid-template-columns:1fr 1fr;gap:10px}.metric>strong{font-size:28px}.metric>div{font-size:10px}.metric small{font-size:9px}.card{padding:20px 15px}.bottom-columns{grid-template-columns:1fr}.outcomes{grid-template-columns:1fr}.section-heading h2{font-size:19px}.live{font-size:8px}.note>div{align-items:start;flex-direction:column;gap:4px}footer{flex-direction:column;gap:8px}.filters label:first-child{flex-basis:100%}.columns>#rapportages{display:block}.ring{width:150px;height:150px}.ring>div{width:122px;height:122px}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}

/* Kleuren uit de bestaande dashboardstijl: donkerblauw, lichtblauw en statusaccenten. */
.topbar{background-color:#183c57;background-image:linear-gradient(90deg,rgba(5,30,55,.94) 0%,rgba(5,30,55,.76) 46%,rgba(5,30,55,.44) 100%),repeating-linear-gradient(90deg,rgba(224,239,248,.13) 0 2px,transparent 2px 68px),repeating-linear-gradient(0deg,rgba(4,22,40,.62) 0 7px,transparent 7px 58px),linear-gradient(120deg,#123854 12%,#315b72 52%,#765e57);background-size:auto,68px 100%,100% 58px,100% 100%;background-position:center;background-blend-mode:normal,screen,normal,normal}
.topbar{color:#fff}.topbar .muted,.topbar .date{color:#bdd4e5}
.sidebar nav a:first-child{box-shadow:inset 3px 0 #079ee9;border-left:3px solid #12a887}
.metric{border-top:3px solid #1689e8}.metric:nth-child(2){border-top-color:#08a68e}.metric:nth-child(3){border-top-color:#ed9410}.metric:nth-child(4){border-top-color:#858ad3}
.metric:nth-child(2)>strong{color:#087e65}
/* Elke menukeuze heeft dezelfde actieve stijl en overgang. */
.sidebar nav a:first-child{background:transparent;color:#e0edf6;box-shadow:none;border-left:0}
.sidebar nav a{border-left:3px solid transparent;transition:background .2s,color .2s,transform .2s}
.sidebar nav a:hover,.sidebar nav a.active{background:#10445f;color:#fff}
.sidebar nav a.active{border-left:3px solid #12a887;box-shadow:inset 3px 0 #079ee9}
.sidebar nav a:hover{transform:translateX(3px)}
.docent-form{display:grid;gap:13px;margin:16px 0}.docent-form label{display:grid;gap:7px;font-size:12px;color:#315463}.docent-form input,.docent-form select,.docent-form textarea{width:100%;padding:11px;border:1px solid #cfe0eb;border-radius:7px;background:white;color:#183c63;font:inherit}.docent-form textarea{resize:vertical}.docent-form .button{justify-self:start}.edit-panel{margin:15px 0;padding:12px;border:1px solid #d5e6f0;border-radius:8px;background:#f7fafc}.edit-panel summary{font-size:12px;color:#1664ac;font-weight:600}.danger{padding:8px 12px;border:1px solid #e6b8bc;border-radius:6px;background:white;color:#a72a39;font-size:11px}.field-error{color:#a72a39;font-size:11px}.notice.success{background:#e6f6ee;color:#087e65}.meeting>div:last-child{min-width:0;flex:1}
@media(prefers-reduced-motion:reduce){.sidebar nav a{transition:none}.sidebar nav a:hover{transform:none}}
/* Acties zijn direct zichtbaar; een opslagbevestiging blijft bij een ankerlink in beeld. */
.student-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.student-actions form{margin:0}.student-actions .button,.student-actions .danger{padding:9px 12px;font-size:11px}.edit-panel summary{padding:7px 0}.save-feedback{position:fixed;right:24px;bottom:24px;max-width:min(480px,calc(100vw - 32px));z-index:20;box-shadow:0 8px 30px #092c4d22}.validation-feedback:focus{outline:3px solid #ed9410}.save-feedback button{margin-left:12px;background:none;border:0;cursor:pointer;color:inherit}
.edit-panel summary.create-student-button{display:list-item;list-style-position:inside;padding:11px 15px;border-radius:7px;background:#1664ac;color:#fff;width:fit-content}
